window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"should":{"senseGroups":[{"id":"source-aux-1","partOfSpeech":"aux.","sourceSenseIds":["aux-1"],"sense":"应该"},{"id":"source-aux-2","partOfSpeech":"aux.","sourceSenseIds":["aux-2"],"sense":"将要"}],"examples":[{"sentence":"Students should check the source of online information before sharing it with classmates.","translation":"学生在向同学转发网络信息前，应当核查其来源。","targetForm":"should","senseId":"source-aux-1","sourceSenseId":"aux-1"},{"sentence":"The bridge should reopen once engineers confirm that the repairs meet safety standards.","translation":"工程师确认维修符合安全标准后，这座桥应会重新开放。","targetForm":"should","senseId":"source-aux-2","sourceSenseId":"aux-2"},{"sentence":"You should allow extra time when travelling during the holiday rush.","translation":"假期出行高峰期间，你应当预留更多时间。","targetForm":"should","senseId":"source-aux-1","sourceSenseId":"aux-1"},{"sentence":"The report should explain not only what changed but also why the change was necessary.","translation":"报告不仅应说明发生了什么变化，也应解释变化为何必要。","targetForm":"should","senseId":"source-aux-1","sourceSenseId":"aux-1"},{"sentence":"Local authorities should consult residents before altering services that many people depend on.","translation":"地方当局在调整许多人依赖的服务前，应当征询居民意见。","targetForm":"should","senseId":"source-aux-1","sourceSenseId":"aux-1"}]},"shove":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"挤"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"推挤"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"猛推"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"强使"}],"examples":[{"sentence":"A sudden shove in the crowded doorway caused several passengers to lose their balance.","translation":"拥挤门口的一次突然推挤使几名乘客失去了平衡。","targetForm":"shove","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Security staff asked visitors not to shove when the doors opened, because the narrow entrance created a risk.","translation":"安保人员要求访客开门时不要推挤，因为狭窄入口会带来风险。","targetForm":"shove","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The worker shoved the heavy trolley aside so that emergency vehicles could reach the damaged building.","translation":"工人把沉重的手推车猛推到一边，以便急救车辆能抵达受损建筑。","targetForm":"shoved","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The rushed timetable shoves teachers into making choices before they have reviewed the evidence properly.","translation":"仓促的时间表迫使教师在尚未充分审阅证据前作出选择。","targetForm":"shoves","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Rather than shoving documents into a drawer, the assistant created a system that made each file easy to retrieve.","translation":"助理没有把文件胡乱塞进抽屉，而是建立了一套使每份文件都易于检索的系统。","targetForm":"shoving","senseId":"source-v-3","sourceSenseId":"v-3"}]},"shock":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"震惊"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"冲击"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"震惊得"}],"examples":[{"sentence":"Although the initial shock of the diagnosis was overwhelming, the patient gradually began to explore treatment options.","translation":"尽管诊断结果带来的最初震惊难以承受，患者还是逐渐开始了解治疗方案。","targetForm":"shock","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When the financial crisis hit, the shock to the banking system exposed weaknesses that regulators had overlooked.","translation":"金融危机来袭时，对银行体系的冲击暴露了监管机构曾忽视的弱点。","targetForm":"shock","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The loss of her job shocked her at first, yet it eventually encouraged her to pursue a more fulfilling career.","translation":"起初，失业使她震惊；但这最终促使她追求一份更有满足感的职业。","targetForm":"shocked","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Because the factory closure delivered a severe economic shock to the community, local leaders introduced emergency relief measures.","translation":"由于工厂关闭给社区带来严重的经济冲击，当地领导人出台了紧急救助措施。","targetForm":"shock","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The unexpected election result shocked many analysts, who then reexamined their assumptions about voter behavior.","translation":"意外的选举结果震惊了许多分析人士，他们随后重新审视了自己对选民行为的假设。","targetForm":"shocked","senseId":"source-v-4","sourceSenseId":"v-4"}]},"sham":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"哄骗"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"赝品"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"假的"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"骗子"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"假装"}],"examples":[{"sentence":"The charity organization was exposed as a complete sham that had misappropriated donations for personal gain.","translation":"该慈善组织被揭露完全是一场骗局，它挪用了捐款谋取私利。","targetForm":"sham","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The art dealer was arrested for selling shams that he had claimed were original works by a famous painter.","translation":"那位艺术品经销商因出售赝品而被捕，他曾声称这些是一位著名画家的原作。","targetForm":"shams","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The committee dismissed the report as a sham document that contained fabricated data and misleading conclusions.","translation":"委员会将该报告斥为一份虚假文件，其中包含捏造的数据和误导性结论。","targetForm":"sham","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"He was eventually recognized as a sham who had deceived investors with his elaborate financial schemes.","translation":"他最终被认出是个骗子，曾用精心设计的金融骗局欺骗投资者。","targetForm":"sham","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The defendant attempted to sham amnesia during the trial, but the prosecution presented evidence of his coherent actions after the incident.","translation":"被告在审判中试图假装失忆，但检方出示了他在事件后行为连贯的证据。","targetForm":"sham","senseId":"source-v-1","sourceSenseId":"v-1"}]},"shiver":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"颤抖"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"哆嗦"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"粉碎"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"战栗"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"使迎风飘动"}],"examples":[{"sentence":"The child shivered uncontrollably as the icy wind cut through her thin jacket.","translation":"当刺骨的寒风穿透她单薄的外套时，那个孩子不由自主地颤抖起来。","targetForm":"shivered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"He was shivering so violently from the fever that his teeth chattered.","translation":"他因发烧而剧烈地哆嗦着，牙齿咯咯作响。","targetForm":"shivering","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The old mirror fell to the floor and shivered into a thousand sharp fragments.","translation":"那面旧镜子掉到地上，粉碎成无数尖锐的碎片。","targetForm":"shivered","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"A sudden shiver ran down her spine when she heard the eerie howl in the distance.","translation":"当她听到远处诡异的嚎叫声时，一阵突如其来的战栗沿着她的脊背窜下。","targetForm":"shiver","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The sailors watched the sail shiver in the light breeze as they drifted slowly.","translation":"水手们看着船帆在微风中轻轻飘动，同时他们缓缓地漂流着。","targetForm":"shiver","senseId":"source-v-4","sourceSenseId":"v-4"}]},"shed":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"小屋"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使流出"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"脱落"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"摆脱"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"放射"}],"examples":[{"sentence":"The gardener stored the lawnmower and various tools inside the wooden shed at the end of the garden.","translation":"园丁将割草机和各种工具存放在花园尽头的木制棚屋里。","targetForm":"shed","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The bereaved mother continued to shed tears long after the funeral had ended.","translation":"葬礼结束后很久，那位丧子的母亲仍在流泪。","targetForm":"shed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Many deciduous trees naturally shed their leaves each autumn as part of their growth cycle.","translation":"许多落叶乔木每年秋天自然会脱落叶子，这是其生长周期的一部分。","targetForm":"shed","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The company is shedding its unprofitable divisions in order to focus on core business activities.","translation":"公司正在剥离其不盈利的部门，以便专注于核心业务活动。","targetForm":"shedding","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The new research findings shed light on the complex mechanisms underlying cellular regeneration.","translation":"新的研究发现揭示了细胞再生背后的复杂机制。","targetForm":"shed","senseId":"source-v-2","sourceSenseId":"v-2"}]},"shoot":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"芽"},{"id":"source-n-9","partOfSpeech":"n.","sourceSenseIds":["n-9"],"sense":"摄影"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"射击"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"拍摄"},{"id":"source-v-14","partOfSpeech":"v.","sourceSenseIds":["v-14"],"sense":"射门"}],"examples":[{"sentence":"When the first green shoots appeared, the gardeners knew that the young plants had survived winter.","translation":"第一批嫩芽出现时，园丁知道这些幼苗已经挺过了冬天。","targetForm":"shoots","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The magazine arranged a photo shoot so that the interview could appear with original portraits.","translation":"这家杂志安排了一次摄影，以便访谈能配上原创肖像照刊出。","targetForm":"shoot","senseId":"source-n-9","sourceSenseId":"n-9"},{"sentence":"At the supervised range, trainees learned to shoot only after the instructor explained the safety rules.","translation":"在受监督的靶场，学员在教练说明安全规则后才学习射击。","targetForm":"shoot","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the forest was dense, the photographer hoped to shoot wildlife without disturbing its habitat.","translation":"尽管森林茂密，摄影师仍希望在不打扰野生动物栖息地的情况下拍摄它们。","targetForm":"shoot","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"When the defender moved closer, the basketball player chose to shoot from the three-point line.","translation":"当防守队员逼近时，这名篮球运动员选择从三分线投篮。","targetForm":"shoot","senseId":"source-v-14","sourceSenseId":"v-14"}]},"short":{"senseGroups":[{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"简短的"}],"examples":[{"sentence":"In short, China is veritably humming with energy, money, plans, leadership, and forward motion, while the West seems paralyzed.","translation":"简而言之，当西方陷入瘫痪之时，中国却在能源、资金、计划和领导层的共同作用下活跃起来，并进一��向前发展。","targetForm":"short","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"In short, the qualities that make foxes more accurate also make them less popular.","translation":"简而言之一句话，使狐狸型专家更为准确的特点也使他们失去了媒体的欢心。","targetForm":"short","senseId":"source-adj-5","sourceSenseId":"adj-5"}]},"shallow":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"水浅的地方"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"浅的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"肤浅的"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"(使)变浅"}],"examples":[{"sentence":"Before crossing the river, the guide led the group toward a shallow where the current was weaker.","translation":"过河前，向导带领队伍走向水流较弱的浅水处。","targetForm":"shallow","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the river becomes shallow during the dry season, cargo vessels must reduce their loads.","translation":"由于河流在旱季变浅，货船必须减少载重。","targetForm":"shallow","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A shallow understanding of history can lead policymakers to repeat mistakes rather than learn from them.","translation":"对历史的肤浅理解可能使决策者重蹈覆辙，而非从中学习。","targetForm":"shallow","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although social media can connect people, shallow interactions may not develop into meaningful relationships.","translation":"尽管社交媒体能连接人们，肤浅的互动未必能发展成有意义的关系。","targetForm":"shallow","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The channel began to shallow after repeated storms deposited sand near the harbour entrance.","translation":"反复的风暴在港口入口附近沉积沙子后，航道开始变浅。","targetForm":"shallow","senseId":"source-v-1","sourceSenseId":"v-1"}]},"shift":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"变化"}],"examples":[{"sentence":"Any religious minority in quest of a place in the European project would do well to reflect on that theological shift.","translation":"任何宗教少数派在欧洲计划中探寻一席之地时，都会仔细考虑其在神学上的转变。","targetForm":"shift","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shortly":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"不久"},{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"简短"},{"id":"source-adv-3","partOfSpeech":"adv.","sourceSenseIds":["adv-3"],"sense":"唐突地"}],"examples":[{"sentence":"The committee will announce its decision shortly after reviewing the final report.","translation":"委员会将在审阅最终报告后不久宣布其决定。","targetForm":"shortly","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"She arrived at the airport shortly before the departure gate closed.","translation":"她在登机口关闭前不久抵达了机场。","targetForm":"shortly","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"The professor explained the complex theory shortly, yet his concise remarks clarified the key points.","translation":"教授简短地解释了这一复杂理论，但他简洁的评论阐明了要点。","targetForm":"shortly","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"When interrupted, he answered shortly and then resumed his work without further comment.","translation":"被打断时，他唐突地回答了一句，然后继续工作，没有再多说。","targetForm":"shortly","senseId":"source-adv-3","sourceSenseId":"adv-3"},{"sentence":"The new policy was introduced shortly after the economic downturn began to affect local businesses.","translation":"新政策在经济衰退开始影响当地企业后不久便出台了。","targetForm":"shortly","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"sheer":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"绝对的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"纯粹的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"透明的"},{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"峻峭的"},{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"完全"}],"examples":[{"sentence":"The sheer scale of the infrastructure project required an unprecedented level of international cooperation and funding.","translation":"该基础设施项目的庞大规模需要前所未有的国际合作和资金支持。","targetForm":"sheer","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her success was attributed to sheer determination, as she overcame obstacles that would have discouraged most people.","translation":"她的成功归因于纯粹的决心，因为她克服了大多数人都望而却步的障碍。","targetForm":"sheer","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The designer chose a sheer fabric for the curtains, allowing soft natural light to filter into the minimalist room.","translation":"设计师为窗帘选择了一种透明的面料，让柔和的自然光透入这间极简风格的房间。","targetForm":"sheer","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The sheer cliffs along the coastline are a result of millions of years of erosion by wind and water.","translation":"海岸线上陡峭的悬崖是数百万年风和水侵蚀的结果。","targetForm":"sheer","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"The mountain rose sheer from the valley floor, its granite face challenging even the most experienced climbers.","translation":"这座山从谷底陡峭地拔地而起，其花岗岩壁甚至挑战了最有经验的登山者。","targetForm":"sheer","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"shot":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"射击"}],"examples":[{"sentence":"His only hope of winning the pool game at that point was to successfully execute a complex trick shot.","translation":"那时他赢得撞球比赛的唯一希望，就是成功打出一记复杂的花式击球。","targetForm":"shot","senseId":"source-n-3","sourceSenseId":"n-3"}]},"shrug":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"耸肩"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"耸肩"}],"examples":[{"sentence":"The manager responded to the criticism with a dismissive shrug, which only intensified the tension in the room.","translation":"经理对批评报以轻蔑的耸肩，这反而加剧了房间里的紧张气氛。","targetForm":"shrug","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When asked about the missing funds, the accountant gave a helpless shrug, suggesting he had no explanation to offer.","translation":"当被问及资金缺失时，会计无奈地耸了耸肩，暗示他无法提供任何解释。","targetForm":"shrug","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She merely shrugged when confronted with the evidence, refusing to acknowledge any wrongdoing on her part.","translation":"面对证据时她只是耸了耸肩，拒绝承认自己有任何不当行为。","targetForm":"shrugged","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Despite the mounting pressure, the diplomat shrugged off the allegations and continued with the negotiations as planned.","translation":"尽管压力越来越大，这位外交官对指控不屑一顾，继续按计划进行谈判。","targetForm":"shrugged","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The seasoned professor often shrugs at minor setbacks, believing that persistence ultimately leads to success.","translation":"这位经验丰富的教授常对小的挫折耸耸肩，认为坚持不懈终会带来成功。","targetForm":"shrugs","senseId":"source-v-1","sourceSenseId":"v-1"}]},"shirt":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"衬衫"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"内衣"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"汗衫"}],"examples":[{"sentence":"Because the ceremony was formal, he ironed a white shirt carefully before leaving for the hall.","translation":"因为仪式很正式，他出发去会场前仔细熨平了一件白衬衫。","targetForm":"shirt","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the shirt was made from fine cotton, it remained comfortable after a long day of travel.","translation":"尽管这件衬衫由优质棉布制成，长途旅行一天后穿着仍很舒适。","targetForm":"shirt","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The nurse advised him to wear a clean shirt next to the skin after the treatment had been completed.","translation":"治疗结束后，护士建议他贴身穿一件干净的内衣。","targetForm":"shirt","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"For the charity run, every volunteer received a bright shirt bearing the name of the local campaign.","translation":"慈善跑活动中，每位志愿者都收到了一件印有当地公益活动名称的鲜艳汗衫。","targetForm":"shirt","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A well-fitted shirt can make a simple suit look more professional without drawing attention away from the speaker.","translation":"一件合身的衬衫能让简单的西装显得更专业，同时不会分散人们对演讲者的注意力。","targetForm":"shirt","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shade":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"荫"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"灯罩"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"浓淡"},{"id":"source-n-7","partOfSpeech":"n.","sourceSenseIds":["n-7"],"sense":"微量"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"遮蔽"}],"examples":[{"sentence":"During the hottest part of the afternoon, the old oak offered enough shade for children to play safely.","translation":"下午最热的时候，老橡树提供了足够的树荫，让孩子们能安全玩耍。","targetForm":"shade","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The reading lamp needed a new shade because the damaged one allowed a harsh light to reach the desk.","translation":"这盏阅读灯需要一个新灯罩，因为破损的灯罩让刺眼的光线照到了书桌上。","targetForm":"shade","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The artist chose a pale shade of blue so that the foreground figures would remain the centre of attention.","translation":"画家选择了淡蓝色调，以便前景人物仍保持视觉焦点。","targetForm":"shade","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"Although the proposals share the same goal, there is a shade of difference in how each defines public responsibility.","translation":"尽管两项提议目标相同，它们对公共责任的界定仍有细微差别。","targetForm":"shade","senseId":"source-n-7","sourceSenseId":"n-7"},{"sentence":"Tall buildings shaded the narrow street for most of the day, which made the pavement slow to dry after rain.","translation":"高楼在一天大部分时间遮蔽了狭窄街道，导致雨后人行道很难干。","targetForm":"shaded","senseId":"source-v-4","sourceSenseId":"v-4"}]},"shabby":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"破旧的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"低劣的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"吝啬的"}],"examples":[{"sentence":"The shabby coat he wore to the interview did not reflect his true professional capabilities.","translation":"他面试时穿的那件破旧外套并不能反映他真正的专业能力。","targetForm":"shabby","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Despite the shabby appearance of the old library, it housed a remarkable collection of rare manuscripts.","translation":"尽管那座旧图书馆外观破旧，但它收藏了一批非凡的珍稀手稿。","targetForm":"shabby","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The company's shabby treatment of its employees led to a high turnover rate and negative publicity.","translation":"公司对员工的低劣待遇导致了高离职率和负面舆论。","targetForm":"shabby","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"His shabby excuse for missing the deadline, which blamed a minor technical glitch, convinced no one on the team.","translation":"他错过截止日期的低劣借口，将责任归咎于一个微小的技术故障，这没能说服团队中的任何人。","targetForm":"shabby","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The landlord's shabby refusal to repair the heating system during winter was both unethical and illegal.","translation":"房东在冬季吝啬地拒绝修理供暖系统，这既不道德也违法。","targetForm":"shabby","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"shopkeeper":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"店主"}],"examples":[{"sentence":"The shopkeeper arranged the imported goods on the shelves with meticulous care each morning.","translation":"这位店主每天早上都一丝不苟地将进口商品摆放在货架上。","targetForm":"shopkeeper","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A local shopkeeper, who had run the bookstore for three decades, decided to retire and sell the property.","translation":"一位经营了三十年书店的当地店主决定退休并出售该房产。","targetForm":"shopkeeper","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The shopkeeper negotiated with the supplier to secure a better price for the organic produce.","translation":"这位店主与供应商谈判，为有机农产品争取到了更优惠的价格。","targetForm":"shopkeeper","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"During the festival, the shopkeeper decorated the storefront with colorful banners to attract customers.","translation":"节日期间，店主用彩色横幅装饰店面以吸引顾客。","targetForm":"shopkeeper","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The elderly shopkeeper remembered every regular customer's preferences, which fostered strong community loyalty.","translation":"那位年长的店主记得每位常客的偏好，这培养了强烈的社区忠诚度。","targetForm":"shopkeeper","senseId":"source-n-2","sourceSenseId":"n-2"}]},"sheet":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"床单"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"纸张"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"薄片"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"大片落下"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"工作表","contextReviewed":true}],"examples":[{"sentence":"The nurse changed the sheet each morning so that the patient could rest in a clean bed.","translation":"护士每天早晨更换床单，让病人能在干净的床上休息。","targetForm":"sheet","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the sheet of paper was thin, it carried detailed diagrams for the engineering workshop.","translation":"尽管这张纸很薄，它仍印有工程研讨会的详细图表。","targetForm":"sheet","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When the metal sheet was heated, workers shaped it gradually to avoid creating weak points.","translation":"金属薄板加热后，工人逐步塑形，以避免形成薄弱点。","targetForm":"sheet","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"The storm sheeted rain across the windows, while the station staff helped passengers indoors.","translation":"暴风雨使雨水大片地打在窗户上，车站工作人员则协助乘客进入室内。","targetForm":"sheeted","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Because the shared sheet was updated automatically, every member could see the latest budget figures.","translation":"由于共享工作表会自动更新，每位成员都能看到最新预算数据。","targetForm":"sheet","senseId":"source-other-1","sourceSenseId":"other-1"}]},"shelter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"庇护所"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"庇护"}],"examples":[{"sentence":"Studies show that once the basic needs of shelter and food are met, additional wealth adds very little to happiness.","translation":"研究表明人们一有住处、食物这些基本的需要，附加的财富就不能大量地提高他们的快乐。","targetForm":"shelter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A shepherd drove his snow-covered goat into an abandoned cave to take shelter from the blizzard.","translation":"一个牧羊人把他一身白雪的山羊赶进被遗弃的山洞躲避暴风雪。","targetForm":"shelter","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A goatherd drove his goats, all white with snow, into a deserted cave for shelter.","translation":"一个牧羊人把他一身白雪的山羊赶进被遗弃的山洞躲避暴风雪。","targetForm":"shelter","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"To escape the storm, we took shelter in a nearby barn.","translation":"为躲避风暴，我们躲到了附近的一个谷仓内。","targetForm":"shelter","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Children depend on their parents for food, clothing and shelter.","translation":"孩子们的衣食住行靠的是他们的父母。","targetForm":"shelter","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shutter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"百叶窗"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"照相机快门"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"为...装百叶窗"}],"examples":[{"sentence":"The old wooden shutters on the cottage were closed every evening to keep out the cold wind.","translation":"小屋上的旧木制百叶窗每晚都关闭，以阻挡寒风。","targetForm":"shutters","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During the storm, we secured the shutters over the windows to protect the glass from flying debris.","translation":"暴风雨期间，我们固定好窗户上的百叶窗，以保护玻璃免受飞溅碎片的伤害。","targetForm":"shutters","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The photographer adjusted the shutter speed to capture the fast-moving wildlife without any blur.","translation":"摄影师调整了快门速度，以清晰地捕捉快速移动的野生动物。","targetForm":"shutter","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A slow shutter can create beautiful light trails in nighttime cityscape photography.","translation":"慢速快门可以在夜间城市风光摄影中创造出美丽的光轨。","targetForm":"shutter","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"They decided to shutter the windows of the beach house before the hurricane season began.","translation":"他们决定在飓风季节开始前为海滨别墅的窗户装上百叶窗。","targetForm":"shutter","senseId":"source-v-1","sourceSenseId":"v-1"}]},"shoulder":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"肩膀"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"肩"}],"examples":[{"sentence":"If you want to have an attractive personality, you need to have a good head on your shoulders.","translation":"要想有良好的人格魅力，必须要有聪慧的头脑。","targetForm":"shoulders","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Those two communicate a lot with each other at work, often rubbing shoulders.","translation":"他们俩工作上联系多，经常打交道。","targetForm":"shoulders","senseId":"source-n-1","sourceSenseId":"n-1"}]},"sharp":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"利刃"}],"examples":[{"sentence":"The sharp decline in stock prices caused widespread panic among investors, which led to a market crash.","translation":"股票价格的急剧下跌引起了投资者的普遍恐慌，进而导致市场崩盘。","targetForm":"sharp","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because her sharp mind allowed her to solve complex problems quickly, she was promoted to lead the research team.","translation":"因为她敏锐的头脑能快速解决复杂问题，她被提升为研究团队的负责人。","targetForm":"sharp","senseId":"source-n-2","sourceSenseId":"n-2"}]},"shop":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"商店"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"车间"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"选购"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"到处寻找"}],"examples":[{"sentence":"Because the local coffee shop buys beans directly from farmers, customers can trace where each blend comes from.","translation":"由于这家本地咖啡店直接向农民采购咖啡豆，顾客能够追溯每种拼配咖啡的来源。","targetForm":"shop","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The machine shop automated several repetitive stages without compromising the precision required for medical parts.","translation":"这家机械车间自动化了几个重复工序，同时没有影响医疗零部件所需的精度。","targetForm":"shop","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Before shopping for a laptop, students should compare battery life, repair options, and the software they actually need.","translation":"购买笔记本电脑前，学生应比较续航、维修选择和自己真正需要的软件。","targetForm":"shopping","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The family shopped around for insurance because the first quotation did not cover travel cancellation.","translation":"这家人为保险到处比较，因为第一份报价不涵盖旅行取消。","targetForm":"shopped","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although the repair shop is hidden in a quiet alley, its careful work attracts collectors from across the country.","translation":"尽管这家维修店藏在安静小巷里，它细致的工作仍吸引了全国各地的收藏者。","targetForm":"shop","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shepherd":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"牧羊人"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"牧羊犬"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"牧师"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"保护者"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"指导"}],"examples":[{"sentence":"Because the shepherd moved the flock to higher ground before the storm, none of the sheep were lost in the flood.","translation":"因为牧羊人在暴风雨前把羊群赶到高地，洪水中没有一只羊丢失。","targetForm":"shepherd","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The shepherd kept the scattered flock together, responding to quiet commands from the farmer across the field.","translation":"这只牧羊犬把分散的羊群聚在一起，回应农民从田野另一端发出的轻声指令。","targetForm":"shepherd","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The village shepherd offered practical support as well as spiritual guidance after several families lost their homes.","translation":"几户家庭失去住所后，村里的牧师既提供实际支持，也给予精神指引。","targetForm":"shepherd","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"In pastoral communities, an experienced shepherd can be a protector of land, animals, and local ecological knowledge.","translation":"在牧区社区，经验丰富的牧羊人可以成为土地、牲畜和当地生态知识的保护者。","targetForm":"shepherd","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The coordinator shepherded the proposal through several reviews, ensuring that every department had a chance to comment.","translation":"协调员引导这项提议通过多轮审查，确保每个部门都有机会提出意见。","targetForm":"shepherded","senseId":"source-v-3","sourceSenseId":"v-3"}]},"shy":{"senseGroups":[{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"羞怯的"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"避开"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"惊跳"}],"examples":[{"sentence":"Although she was shy at first, she grew more confident after joining the discussion group.","translation":"尽管她起初害羞，加入讨论小组后逐渐更有信心。","targetForm":"shy","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The shy student prepared carefully so that she could share one idea during the meeting.","translation":"这位羞怯的学生认真准备，以便能在会议上分享一个想法。","targetForm":"shy","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"When investors shy away from uncertain markets, they often look for more stable options.","translation":"当投资者回避不确定市场时，他们往往寻找更稳定的选择。","targetForm":"shy","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The horse shied at the sudden noise, although its handler quickly reassured it.","translation":"马被突然的声音惊得一跳，尽管训练员很快安抚了它。","targetForm":"shied","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the team did not shy from difficult questions, it found a more practical solution.","translation":"由于团队没有回避难题，它找到了更实际的解决方案。","targetForm":"shy","senseId":"source-v-5","sourceSenseId":"v-5"}]},"shampoo":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"洗发剂"}],"examples":[{"sentence":"Although the shampoo was marketed as hypoallergenic, some users still experienced scalp irritation due to individual sensitivities.","translation":"尽管这款洗发水被宣传为低过敏性，但由于个体敏感性，一些用户仍然经历了头皮刺激。","targetForm":"shampoo","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The company reformulated its best-selling shampoo to exclude parabens, thereby addressing growing consumer concerns about chemical additives.","translation":"该公司重新配制了其最畅销的洗发水，去除了对羟基苯甲酸酯，从而回应了消费者对化学添加剂日益增长的担忧。","targetForm":"shampoo","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the new shampoo contains argan oil, it effectively moisturizes dry hair and reduces frizz throughout the day.","translation":"由于这款新洗发水含有摩洛哥坚果油，它能有效滋润干燥的头发，并在一整天内减少毛躁。","targetForm":"shampoo","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Dermatologists recommend using a sulfate-free shampoo, which cleanses the scalp gently without stripping away natural oils.","translation":"皮肤科医生建议使用无硫酸盐的洗发水，它能温和清洁头皮而不洗去天然油脂。","targetForm":"shampoo","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When traveling, it is convenient to carry a solid shampoo bar, which saves space and complies with airline liquid restrictions.","translation":"旅行时，携带固体洗发皂很方便，它节省空间并符合航空公司的液体限制。","targetForm":"shampoo","senseId":"source-n-2","sourceSenseId":"n-2"}]},"shortcoming":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"缺点"}],"examples":[{"sentence":"I am not without my shortcomings, but these shortcomings can easily be amended.","translation":"我是个有缺点的人，但这些缺点很容易就能被改正。","targetForm":"shortcomings","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"From the practical point of view, there are many shortcomings in his plan.","translation":"从现实的角度看，他的计划有很多缺点。","targetForm":"shortcomings","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shrewd":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"精明的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"锐利的"}],"examples":[{"sentence":"Her shrewd reading of the contract identified a clause that would have transferred an unreasonable share of risk.","translation":"她对合同的精明解读发现了一项会转移不合理风险份额的条款。","targetForm":"shrewd","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the offer looked generous, the director made a shrewd decision to examine its long-term obligations first.","translation":"尽管报价看起来优厚，主任仍作出精明决定，先审查其长期义务。","targetForm":"shrewd","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The journalist's shrewd questions revealed inconsistencies that a more superficial interview might have missed.","translation":"记者敏锐的问题揭示了较为肤浅的采访可能遗漏的不一致之处。","targetForm":"shrewd","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A shrewd negotiator considers what the other side needs, because mutual benefit often produces a more durable agreement.","translation":"精明的谈判者会考虑对方需求，因为互利往往产生更持久的协议。","targetForm":"shrewd","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The critic offered a shrewd observation about the film's structure, which helped the audience see why its ending felt unsettled.","translation":"评论家对影片结构作出敏锐观察，帮助观众理解为何结尾令人不安。","targetForm":"shrewd","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"shave":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"刮胡子"}],"examples":[{"sentence":"A barber is a man who shaves and cuts men's hair.","translation":"理发师是为男人刮胡子和剪头发的人。","targetForm":"shaves","senseId":"source-n-2","sourceSenseId":"n-2"}]},"shut":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"关闭"}],"examples":[{"sentence":"Keep your eyes wide open before marriage, half shut afterwards.","translation":"婚前张开眼，婚后半闭眼。","targetForm":"shut","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I shut the door quietly so as not to wake the baby.","translation":"为了不吵醒宝宝，我静静地关上了门。","targetForm":"shut","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He was drunk and forgot to shut the back door.","translation":"他醉得忘了把门关上。","targetForm":"shut","senseId":"source-n-1","sourceSenseId":"n-1"}]},"sheep":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"羊"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"胆小者"}],"examples":[{"sentence":"The shepherd moved the sheep to higher ground before the storm, where the animals could avoid the flooded valley.","translation":"暴风雨来临前，牧羊人把羊群赶到高地，使它们避开被淹山谷。","targetForm":"sheep","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although sheep farming depends on seasonal conditions, careful grazing can protect grassland rather than exhaust it.","translation":"尽管养羊依赖季节条件，谨慎放牧可以保护草地而非耗尽它。","targetForm":"sheep","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The exhibition explained how sheep's wool supported local weaving industries long before factory production became common.","translation":"展览说明，在工厂生产普及很久之前，羊毛如何支撑当地纺织业。","targetForm":"sheep","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The columnist warned that voters should not follow political slogans like sheep when evidence points in another direction.","translation":"专栏作者提醒，若证据指向另一方向，选民不应像羊群一样盲从政治口号。","targetForm":"sheep","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Researchers monitored each sheep's movement so that the flock could be protected without disturbing its usual grazing pattern.","translation":"研究人员监测每只羊的移动，以便保护羊群而不打扰其通常的放牧模式。","targetForm":"sheep","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shipment":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"运送的货物","contextReviewed":true},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"出货"}],"examples":[{"sentence":"The shipment arrived with a complete inventory, allowing the museum to check every borrowed object before unpacking.","translation":"这批货物附有完整清单，让博物馆能在拆包前核对每件借展物品。","targetForm":"shipment","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Because the shipment contained fragile glass, the team used reusable crates rather than loose cardboard packaging.","translation":"由于这批货物包含易碎玻璃，团队使用了可重复使用的板条箱，而非松散纸板包装。","targetForm":"shipment","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The supplier confirmed the shipment only after each document had been checked against the export requirements.","translation":"每份文件都按出口要求核对后，供应商才确认发货。","targetForm":"shipment","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the shipment was delayed, the warehouse reorganised its schedule so that local orders could still be filled.","translation":"尽管货物延误，仓库仍重新安排了日程，使本地订单能够照常完成。","targetForm":"shipment","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The tracking page showed that the shipment had left the port and was moving toward the regional distribution centre.","translation":"追踪页面显示货物已离开港口，正运往区域配送中心。","targetForm":"shipment","senseId":"source-n-5","sourceSenseId":"n-5"}]},"shuttle":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"往返移动之物"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"梭子"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"(使)穿梭移动"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"往返运送"}],"examples":[{"sentence":"The campus shuttle leaves every fifteen minutes, so students can reach the science building without changing buses.","translation":"校园班车每十五分钟一班，因此学生无需换车就能到达科学楼。","targetForm":"shuttle","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"During the exhibition, a small shuttle carried visitors between the railway station and the gallery.","translation":"展览期间，一辆小型接驳车在火车站和美术馆之间往返运送参观者。","targetForm":"shuttle","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"In traditional weaving, the shuttle passes the weft through the threads that have been stretched on the loom.","translation":"在传统织造中，梭子把纬线穿过织机上拉紧的经线。","targetForm":"shuttle","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before the interview, the reporter shuttled between two offices to confirm the figures with both teams.","translation":"采访前，记者在两间办公室之间来回奔走，向两个团队核实数据。","targetForm":"shuttled","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The organisers shuttled speakers from the airport to the venue while volunteers prepared the registration desk.","translation":"志愿者准备签到台时，组织者把演讲者从机场往返接送到会场。","targetForm":"shuttled","senseId":"source-v-2","sourceSenseId":"v-2"}]},"ship":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"船"}],"examples":[{"sentence":"The wreckage of the ship was salvaged after it had gone to Davy Jones's locker.","translation":"船的残骸从海底被打捞上来。","targetForm":"ship","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shark":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"鲨鱼"}],"examples":[{"sentence":"Such action must not only aim to protect shark populations directly; it must also address major threats to sharks, such as illegal trade, bycatch, and overfishing.","translation":"此类行动不仅要致力于鲨鱼种群的直接保护；还必须消除非法贸易、误捕以及过度捕捞等鲨鱼所面临的主要威胁。","targetForm":"shark","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The skin of a shark is much rougher than that of a tuna fish.","translation":"鲨鱼的皮比鲔鱼的皮粗糙多了。","targetForm":"shark","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Sharks are sensitive to electrical impulses as well as sound.","translation":"鲨鱼对电子信号和噪音很敏感。","targetForm":"sharks","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shoe":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"鞋"}],"examples":[{"sentence":"In Asian culture it's customary to take one's shoes off before entering a house or temple.","translation":"在亚洲文化里，习惯在进一个房子或一座寺庙前先脱鞋子。","targetForm":"shoes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I make it a point to shine my shoes before I go to bed.","translation":"我提出这一点之前，我的鞋和我去睡觉。","targetForm":"shoes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The first thing I did when I got home was take my shoes off.","translation":"我到家后做的第一件事便是脱鞋。","targetForm":"shoes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Visitors are usually asked to remove their shoes before they enter a Japanese house.","translation":"访客通常在进入一户日本人家之前会被要求脱鞋。","targetForm":"shoes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I doubt if Mary would do that if she were in your shoes.","translation":"我怀疑如果玛丽处在你的位置上是否还会那样做。","targetForm":"shoes","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shelf":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"架子"}],"examples":[{"sentence":"Tom reached for a dictionary that was on the very top of the shelf.","translation":"汤姆把手伸向了书架上最高的一本词典。","targetForm":"shelf","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He put the books on the shelf out of order.","translation":"他胡乱把书本放在架上。","targetForm":"shelf","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She put her CDs in a row on the shelf.","translation":"她把她的CD在书架上排成一排。","targetForm":"shelf","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shell":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"壳"}],"examples":[{"sentence":"This farm's free-range eggs have a deeper shell color, and the yolks are especially rich and delicious.","translation":"这家农场的草鸡蛋颜色偏深，蛋黄特别鲜美。","targetForm":"shell","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The eggs from this farm have darker shells, and the yolks are exceptionally rich.","translation":"这家农场的草鸡蛋颜色偏深，蛋黄特别鲜美。","targetForm":"shells","senseId":"source-n-2","sourceSenseId":"n-2"}]},"shadow":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"阴影"}],"examples":[{"sentence":"WASHINGTON, DC – I grew up in the shadow of World War II, and at the dawn of the Cold War.","translation":"华盛顿—我成长于二战的阴影和冷战的黎明中。","targetForm":"shadow","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shame":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"羞耻"}],"examples":[{"sentence":"To address poverty-related shame, and adequately account for the role shame plays in perpetuating poverty, a number of steps must be taken.","translation":"要解决与贫困有关的羞耻，充分考虑羞耻在导致贫困长期化中所起的作用，需要采取一系列措施。","targetForm":"shame","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It's a crying shame that they weren't insured against fire.","translation":"这简直是太可惜了，他们没有买火险。","targetForm":"shame","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shrink":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"萎缩"}],"examples":[{"sentence":"Fruit that has been left for a long time will shrink.","translation":"水果放久了，就会萎缩。","targetForm":"shrink","senseId":"source-n-2","sourceSenseId":"n-2"}]},"shower":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"阵雨"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"淋浴"}],"examples":[{"sentence":"I'm glad we didn't go there because there were some localized heavy rain showers.","translation":"我很庆幸我们没有去那儿，因为当时那儿有局部大暴雨。","targetForm":"showers","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"As I returned from school yesterday, I was caught in a sudden shower.","translation":"昨天我在放学回家的路上突然遇上了一阵大雨。","targetForm":"shower","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Yesterday I was caught in a shower on my way home from school.","translation":"我昨天放学回家的时候突然下起了大雨。","targetForm":"shower","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I am in the habit of taking a shower in the morning.","translation":"我习惯早上洗澡。","targetForm":"shower","senseId":"source-n-2","sourceSenseId":"n-2"}]},"shout":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"呼喊"}],"examples":[{"sentence":"All at once she began to shout in a shrill voice.","translation":"突然间她开始用尖锐的声音大喊。","targetForm":"shout","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shake":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"摇动"}],"examples":[{"sentence":"When you shake hands with somebody, you must look him in the eye.","translation":"和别人握手的时候，一定要有眼神接触。","targetForm":"shake","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shape":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"形式"}],"examples":[{"sentence":"Nonetheless, the mindset nurtured by The Limits to Growth continues to shape popular and elite thinking.","translation":"尽管如此 ， 《 增长的极限》所培养的观念仍在左右公众和精英的思维。","targetForm":"shape","senseId":"source-n-4","sourceSenseId":"n-4"}]},"show":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"显示"}],"examples":[{"sentence":"Both examples show that Europe, like the US, is vulnerable to the politics of division, as our societies become more ethnically diverse.","translation":"这两个例子都显示出随着我们的社会在种族上越来越多元化，欧洲也无法克服随之诱发的政治分裂现象，正如美国一样。","targetForm":"show","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"However, such incentives do not address the problem of low-quality education, and research shows that the benefits do not always outweigh the costs.","translation":"然而，这种激励措施并没有解决教育质量低的问题，并且研究表明其利益并不总是超出成本。","targetForm":"shows","senseId":"source-n-1","sourceSenseId":"n-1"}]},"shall":{"senseGroups":[{"id":"source-aux-1","partOfSpeech":"aux.","sourceSenseIds":["aux-1"],"sense":"将"}],"examples":[{"sentence":"He that hears much and speaks not at all shall be welcome both in bower and hall.","translation":"多听不多言, 里外人不嫌。","targetForm":"shall","senseId":"source-aux-1","sourceSenseId":"aux-1"},{"sentence":"I am afraid that I shall not be free till the examination is over.","translation":"恐怕直到考试结束前我都没空。","targetForm":"shall","senseId":"source-aux-1","sourceSenseId":"aux-1"},{"sentence":"He who helps others, in turn shall be helped by them.","translation":"助人者得人助。","targetForm":"shall","senseId":"source-aux-1","sourceSenseId":"aux-1"},{"sentence":"We shall fix all bugs today before leaving the office.","translation":"我们应该在今天下班前解决所有bug。","targetForm":"shall","senseId":"source-aux-1","sourceSenseId":"aux-1"}]},"shine":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"光泽"}],"examples":[{"sentence":"If India’s other states – and the central government – can follow this example, then the polish of India will not lose its shine.","translation":"如果印度的其他各邦 — — 以及中央政府 — — 可以把这个邦作为榜样的话，那么印度将永放光芒。","targetForm":"shine","senseId":"source-n-1","sourceSenseId":"n-1"}]}}};
